  const [tokenOrderBookMap, setTokenOrderBookMap] = useMarketState('tokenOrderBookMap');
  const [positions, setPositions] = useMarketState('positions');
  // 【宏观库存池】玩家代币资产分布：CEX 余额 / 链上钱包余额 / 在途资金（第二阶段基础结构）
