  // 【第三部分】CEX / 链上钱包双系统
  const [appSystem, setAppSystem] = useTrackedState<'cex' | 'wallet'>("appSystem", () => {
    try { return localStorage.getItem('app-system-mode') === 'wallet' ? 'wallet' : 'cex'; } catch (e) { return 'cex'; }
  });
  // 链上钱包中的 USDT（独立于 CEX 可用资金）
  const [walletUsdt, setWalletUsdt] = useTrackedState("walletUsdt", 0);
  // 充提币在途资金（次回合到账）
  const [pendingTransfers, setPendingTransfers] = useTrackedState<PendingTransfer[]>("pendingTransfers", []);
  // 链上钱包中的 DEX 流动性份额
  const [walletLpPositions, setWalletLpPositions] = useTrackedState<Record<string, WalletLpPosition>>("walletLpPositions", {});
  // 【第五部分】各代币 CEX 库存量历史（每回合结束时记录，用于数据页库存走势与抛压预警）
  const setCexReserveHistory = useMarketSetter('cexReserveHistory');

  // 【库存守恒】cexBalance（交易所现货可用余额）与 positions（持仓）是两套账本，禁止由持仓强制覆盖。
  // reconcileCexBalances 仅用于旧存档迁移/初始化；买卖结算与充提币必须显式维护 cexBalance。
  const [orders, setOrders] = useMarketState('orders');
  const [orderHistory, setOrderHistory] = useTrackedState<OrderHistory[]>("orderHistory", []);

  // ===== 质押借币（AAVE / Compound / MakerDAO）状态 =====
  const [loanPositions, setLoanPositions] = useTrackedState<LoanPosition[]>("loanPositions", []);
  const [showLoanModal, setShowLoanModal] = useTrackedState("showLoanModal", false); // 质押借币弹窗
  const [loanProtocolId, setLoanProtocolId] = useTrackedState<LoanProtocolId | null>("loanProtocolId", null); // 已选协议
  const [loanTokenId, setLoanTokenId] = useTrackedState("loanTokenId", ''); // 已选质押代币
  const [loanCollateralInput, setLoanCollateralInput] = useTrackedState("loanCollateralInput", ''); // 质押数量输入
  const [loanBorrowInput, setLoanBorrowInput] = useTrackedState("loanBorrowInput", ''); // 借款金额输入（USDT）
  const [repayLoanId, setRepayLoanId] = useTrackedState<string | null>("repayLoanId", null); // 还款弹窗对应的仓位
  const [repayPercent, setRepayPercent] = useTrackedState("repayPercent", 100); // 还款比例（%）
  const [liquidationNotices, setLiquidationNotices] = useTrackedState<Array<{ tokenCode: string; soldQuantity: number; avgPrice: number; proceeds: number; writtenOff: number }> | null>("liquidationNotices", null); // 强制清算红字弹窗
  const [tierLoanNotices, setTierLoanNotices] = useTrackedState<Array<{ tokenCode: string; oldTierLabel: string; newTierLabel: string; deadlineRound: number }> | null>("tierLoanNotices", null); // tier 降级赎回提醒
  const lastLoanProcessRoundRef = useRef<number>(-1); // 每回合清算/tier 检查去重
  const lastAiArbitrageRoundRef = useRef<number>(-1);
  const settledTransferIdsRef = useRef(new Set<string>());
  const lastManualAirdropRoundRef = useRef<Record<string, number>>({}); // 玩家手动空投回合记录（避免同回合套利搬库存） // 【第四部分】每回合 AI 宏观套利去重

  // 已质押（锁定）数量：质押借币改为链上钱包抵押后，质押中的代币不能充值进 CEX 或在 DEX 卖出
  const lockedCollateralByToken = useMemo(() => getLockedCollateralMap(loanPositions), [loanPositions]);
  const getAvailableTokenQuantity = useCallback((tokenId: string): number => {
    // CEX 现货持仓不再被质押锁定，返回全部持仓
    return positions.find(p => p.tokenId === tokenId)?.quantity || 0;
  }, [positions]);
  // 链上钱包可用数量（扣除质押中的代币）
  const getWalletAvailableToken = useCallback((tokenId: string): number => {
    const walletBalance = playerTokenBalances[tokenId]?.walletBalance || 0;
    return Math.max(0, walletBalance - (lockedCollateralByToken[tokenId] || 0));
  }, [playerTokenBalances, lockedCollateralByToken]);

  // 【库存守恒】显式维护玩家 CEX 现货可用余额（买卖结算 / 充提币 / 空投 / 销毁 / 发行等路径必须调用）
  const adjustCexBalance = useCallback((tokenId: string, delta: number) => {
    if (!tokenId || !Number.isFinite(delta) || Math.abs(delta) < 1e-12) return;
    setPlayerTokenBalances(prev => {
      const entry = prev[tokenId] || { cexBalance: 0, walletBalance: 0, pendingCex: 0, pendingWallet: 0 };
      return { ...prev, [tokenId]: { ...entry, cexBalance: Math.max(0, entry.cexBalance + delta) } };
    });
  }, []);
  
  const [availableCapital, setAvailableCapital] = useTrackedState("availableCapital", 5000000);
  const [frozenCapital, setFrozenCapital] = useTrackedState("frozenCapital", 0);
  const [initialCapital, setInitialCapital] = useTrackedState("initialCapital", 5000000);
  const [totalAsset, setTotalAsset] = useTrackedState("totalAsset", 5000000);
  const [roi, setRoi] = useTrackedState("roi", 0);
  const [assetHistory, setAssetHistory] = useTrackedState<number[]>("assetHistory", []); // 总资产历史记录（近24回合）
  const [showAssetChart, setShowAssetChart] = useTrackedState("showAssetChart", false); // 是否显示总资产折线图
  const [homeMarketTab, setHomeMarketTab] = useTrackedState<'hot' | 'gainers' | 'losers'>("homeMarketTab", 'hot'); // 首页行情Tab
  const [marketSectorTab, setMarketSectorTab] = useTrackedState<string>("marketSectorTab", 'all'); // 行情界面板块Tab
  const [marketSearchQuery, setMarketSearchQuery] = useTrackedState("marketSearchQuery", ''); // 行情页面搜索关键词
  const [marketSortField, setMarketSortField] = useTrackedState<'name' | 'price' | 'change' | 'marketCap' | 'volume'>("marketSortField", 'marketCap'); // 行情页面排序字段
  const [marketSortDirection, setMarketSortDirection] = useTrackedState<'asc' | 'desc'>("marketSortDirection", 'desc'); // 行情页面排序方向
  
  const [tradeSide, setTradeSide] = useTrackedState<'buy' | 'sell'>("tradeSide", 'buy');
  const [orderType, setOrderType] = useTrackedState<'market' | 'limit'>("orderType", 'market');
  const [tradePrice, setTradePrice] = useTrackedState("tradePrice", '');
  const [tradeQuantity, setTradeQuantity] = useTrackedState("tradeQuantity", '');
  const [inputMode, setInputMode] = useTrackedState<'quantity' | 'amount'>("inputMode", 'quantity');
  const [tradeAmountPercent, setTradeAmountPercent] = useTrackedState("tradeAmountPercent", 100); // 现货交易金额百分比

  // 流动性池状态（宏观物理库存池将在后续阶段重建）
  const [liquidityPools, setLiquidityPools] = useTrackedState<LiquidityPoolMap>("liquidityPools", {}); // AMM流动性池映射
  const [klineOffset, setKlineOffset] = useTrackedState("klineOffset", 0);
  const [klineScale, setKlineScale] = useTrackedState("klineScale", 1); // K线缩放比例
  const [klinePeriod, setKlinePeriod] = useTrackedState<'1h' | '4h' | '1d'>("klinePeriod", '1h'); // K线周期
  // K线图表设置（订单/仓位显示 + 视图模式），持久化到 localStorage
  const [klineViewSettings, setKlineViewSettings] = useTrackedState<{
    showOrders: boolean;
    showHistory: boolean;
    showPosition: boolean;
    logScale: boolean;
    inverted: boolean;
    percentScale: boolean;
  }>("klineViewSettings", () => {
    try {
      const raw = localStorage.getItem('kline-view-settings-v2');
      if (raw) {
        const parsed = JSON.parse(raw) as Partial<{ showOrders: boolean; showHistory: boolean; showPosition: boolean; logScale: boolean; inverted: boolean; percentScale: boolean }>;
        return {
          showOrders: parsed.showOrders === true,
          showHistory: parsed.showHistory === true,
          showPosition: parsed.showPosition === true,
          logScale: parsed.logScale === true,
          inverted: parsed.inverted === true,
          percentScale: parsed.percentScale === true,
        };
      }
    } catch (e) { /* ignore */ }
    return { showOrders: false, showHistory: false, showPosition: false, logScale: false, inverted: false, percentScale: false };
  });
  const [showKlineSettings, setShowKlineSettings] = useTrackedState("showKlineSettings", false);
  const updateKlineViewSetting = useCallback((key: 'showOrders' | 'showHistory' | 'showPosition' | 'logScale' | 'inverted' | 'percentScale', value: boolean) => {
    setKlineViewSettings(prev => {
      const next = { ...prev, [key]: value };
      try { localStorage.setItem('kline-view-settings-v2', JSON.stringify(next)); } catch (e) { /* ignore */ }
      return next;
    });
  }, []);
  const renderKlineSettingToggle = (key: 'showOrders' | 'showHistory' | 'showPosition' | 'logScale' | 'inverted' | 'percentScale', label: string, desc: string) => (
    <div className="kline-settings-item" key={key}>
      <div className="kline-settings-item-text">
        <span className="kline-settings-item-label">{label}</span>
        <span className="kline-settings-item-desc">{desc}</span>
      </div>
      <button
        type="button"
        className={`kline-switch ${klineViewSettings[key] ? 'on' : ''}`}
        onClick={() => updateKlineViewSetting(key, !klineViewSettings[key])}
        data-testid={`kline-toggle-${key}`}
      >
        <span className="kline-switch-dot" />
      </button>
    </div>
  );
  const [tokenDetailTab, setTokenDetailTab] = useTrackedState<'quote' | 'info' | 'data' | 'community'>("tokenDetailTab", 'quote'); // 代币详情页顶部导航
  const [showFullscreen, setShowFullscreen] = useTrackedState<'chart' | 'orderbook' | 'futures-orderbook' | 'depth' | null>("showFullscreen", null);
  const [showTokenSearchModal, setShowTokenSearchModal] = useTrackedState("showTokenSearchModal", false); // 代币搜索弹窗
  const [tokenSearchQuery, setTokenSearchQuery] = useTrackedState("tokenSearchQuery", ''); // 代币搜索关键词
  const [hasKlineMoved, setHasKlineMoved] = useTrackedState("hasKlineMoved", false);
  const [klineSelectedCandle, setKlineSelectedCandle] = useTrackedState<number | null>("klineSelectedCandle", null); // 点击选中的K线下标（相对可见K线数组）
  const [klineTapPos, setKlineTapPos] = useTrackedState<{ x: number; y: number } | null>("klineTapPos", null); // 点击位置（相对K线区域左上角）
  // 价格变动闪烁（仅视觉反馈，不影响游戏机制）
  // 价格闪烁已迁入 marketStore（盘口组件自行订阅，App 不再因它重渲染）
  const lastPriceRef = useRef<number | null>(null);
  const priceFlashTickRef = useRef(0);
  
  const [activeTab, setActiveTab] = useTrackedState<'home' | 'market' | 'trade' | 'futures' | 'assets'>("activeTab", 'home');
  const [showInitModal, setShowInitModal] = useTrackedState("showInitModal", true);
  const [initCapital, setInitCapital] = useTrackedState("initCapital", 5000000);
  const [toast, setToast] = useTrackedState<{ message: string; type: 'success' | 'error' } | null>("toast", null);
  
  const [currentRound, setCurrentRound] = useTrackedState("currentRound", 0);

  // 【开发自检】现货限价单撮合：资金/冻结/持仓市值守恒（纯函数，不依赖任何 React 状态）
  useEffect(() => {
    if (!import.meta.env.DEV) return;
      (window as unknown as Record<string, unknown>).__SPOT_MATCH_TEST__ = (opts?: {
        side?: 'buy' | 'sell'; price?: number; fillPrice?: number; qty?: number;
        cash?: number; frozen?: number; positionQty?: number;
      }) => {
        const side = opts?.side || 'buy';
        const price = opts?.price ?? 100;
        const fillPrice = opts?.fillPrice ?? 99;
        const qty = opts?.qty ?? 10;
        const cashBefore = opts?.cash ?? 100000;
        const frozenBefore = opts?.frozen ?? price * qty;
        const positionQtyBefore = opts?.positionQty ?? 5;
        const markPrice = fillPrice;
        const book = {
          bids: side === 'buy'
            ? [{ price: fillPrice - 1, quantity: 1000, total: (fillPrice - 1) * 1000 }]
            : [{ price: fillPrice, quantity: 1000, total: fillPrice * 1000 }],
          asks: side === 'buy'
            ? [{ price: fillPrice, quantity: 1000, total: fillPrice * 1000 }]
            : [{ price: fillPrice - 1, quantity: 1000, total: (fillPrice - 1) * 1000 }],
          lastPrice: markPrice,
          totalBidQuantity: 1000,
          totalAskQuantity: 1000,
        } as unknown as Level2OrderBook;
        const order = {
          id: 'test-order', tokenId: 'test-token', tokenCode: 'TST', tokenName: 'Test',
          side, orderType: 'limit', price, quantity: qty, filledQuantity: 0,
          status: 'pending', createdAt: 0,
        } as unknown as Order;
        const res = matchSpotLimitOrders({
          orders: [order], tokenId: 'test-token', tokenName: 'Test', tokenCode: 'TST',
          book, filledAt: 1, makeId: () => 'test-id',
        });
        const positionsBefore: Position[] = positionQtyBefore > 0
          ? [{ id: 'p1', tokenId: 'test-token', quantity: positionQtyBefore, avgCost: fillPrice, currentPrice: fillPrice, marketValue: positionQtyBefore * fillPrice, profitLoss: 0 }]
          : [];
        const positionsAfter = applySpotPositionDeltas(positionsBefore, res.positionDeltas, () => 'p2');
        const posValue = (ps: Position[]) => ps.reduce((sum, p) => sum + p.quantity * p.currentPrice, 0);
        const before = cashBefore + frozenBefore + posValue(positionsBefore);
        const after = cashBefore + res.cashDelta + frozenBefore + res.frozenDelta + posValue(positionsAfter);
        return {
          side, price, fillPrice, qty, cashBefore, frozenBefore,
          cashDelta: res.cashDelta, frozenDelta: res.frozenDelta,
          positionDeltas: res.positionDeltas, cexBalanceDeltas: res.cexBalanceDeltas,
          filledOrderCount: res.filledOrderCount, updatedOrders: res.updatedOrders.length,
          orderHistory: res.orderHistory.length, before, after, diff: after - before,
        };
      };
    (window as unknown as Record<string, unknown>).__FUTURES_MATCH_TEST__ = (opts?: {
      side?: 'open_long' | 'open_short' | 'close_long' | 'close_short';
      price?: number; quantity?: number; exchangeDown?: boolean;
      makeOwnLevel?: boolean;
      bid?: { price: number; quantity: number } | null;
      ask?: { price: number; quantity: number } | null;
    }) => {
      const side = opts?.side || 'open_long';
      const price = opts?.price ?? 100;
      const quantity = opts?.quantity ?? 495;
      const mkLevel = (lv: { price: number; quantity: number } | null | undefined) => lv
        ? {
            price: lv.price,
            quantity: lv.quantity,
            total: lv.price * lv.quantity,
            isPlayer: !!opts?.makeOwnLevel,
            orderId: opts?.makeOwnLevel ? 'own-order' : undefined,
          }
        : null;
      const bid = mkLevel(opts?.bid === undefined ? { price: 100, quantity: 1000 } : opts.bid);
      const ask = mkLevel(opts?.ask === undefined ? { price: 99, quantity: 5 } : opts.ask);
      const book = {
        bids: bid ? [bid] : [],
        asks: ask ? [ask] : [],
        lastPrice: 99,
        totalBidQuantity: bid ? bid.quantity : 0,
        totalAskQuantity: ask ? ask.quantity : 0,
        playerOrderFills: {},
      } as unknown as FuturesOrderBook;
      const order = {
        id: 'fut-test-order', tokenId: 'fut-token', tokenSymbol: 'TST', side,
        orderType: 'limit', price, quantity, filledQuantity: 0,
        status: 'pending', createdAt: 0,
      } as unknown as FuturesOrder;
      const res = matchFuturesLimitOrders({
        orders: [order],
        bookMap: { 'fut-token': book },
        exchangeDown: !!opts?.exchangeDown,
        openBlockedTokenIds: new Set<string>(),
      });
      const outBook = res.updatedBooks['fut-token'];
      const firstOrder = res.processedOrders[0];
      // 输入侧盘口快照：如果纯函数原地改了入参，这里的 quantity 会跟着变
      const inputBook = book as unknown as FuturesOrderBook;
      return {
        side, price, quantity,
        filledCount: res.filledOrders.length,
        fill: res.filledOrders[0] || null,
        order: firstOrder ? {
          status: firstOrder.status,
          filledQuantity: firstOrder.filledQuantity,
          filledTokenQty: firstOrder.filledTokenQty || 0,
          totalCost: firstOrder.totalCost || 0,
        } : null,
        book: outBook ? {
          bids: outBook.bids.map(b => ({ price: b.price, quantity: b.quantity })),
          asks: outBook.asks.map(a => ({ price: a.price, quantity: a.quantity })),
        } : null,
        inputBook: {
          bids: inputBook.bids.map(b => ({ price: b.price, quantity: b.quantity })),
          asks: inputBook.asks.map(a => ({ price: a.price, quantity: a.quantity })),
        },
      };
    };
    (window as unknown as Record<string, unknown>).__FUTURES_CROSS_TEST__ = (opts?: {
      bidPrice?: number; bidQty?: number; askPrice?: number; askQty?: number;
      skip?: boolean; blocked?: boolean;
    }) => {
      const bidPrice = opts?.bidPrice ?? 101;
      const bidQty = opts?.bidQty ?? 10;
      const askPrice = opts?.askPrice ?? 100;
      const askQty = opts?.askQty ?? 5;
      const bid = { price: bidPrice, quantity: bidQty, total: bidPrice * bidQty, isPlayer: true, orderId: 'cross-bid' };
      const ask = { price: askPrice, quantity: askQty, total: askPrice * askQty, isPlayer: false };
      const book = {
        bids: [bid], asks: [ask], lastPrice: 100.5,
        totalBidQuantity: bidQty, totalAskQuantity: askQty, playerOrderFills: {},
      } as unknown as FuturesOrderBook;
      const res = matchFuturesCrossBook({
        books: { 'cross-token': book },
        skip: !!opts?.skip,
        openBlockedTokenIds: new Set<string>(opts?.blocked ? ['cross-token'] : []),
      });
      const out = res.books['cross-token'];
      return {
        fills: res.fills,
        price: res.afterFillPrices['cross-token'] ?? null,
        bids: out.bids.map(b => ({ price: b.price, quantity: b.quantity })),
        asks: out.asks.map(a => ({ price: a.price, quantity: a.quantity })),
        inputBidQty: book.bids[0].quantity,
        inputAskQty: book.asks[0].quantity,
      };
    };

    (window as unknown as Record<string, unknown>).__FUTURES_SETTLE_TEST__ = (opts?: { mode?: 'open' | 'close' | 'partial' }) => {
      const mode = opts?.mode ?? 'open';
      const positions: FuturesPosition[] = mode === 'open' ? [] : [{
        id: 'pos-1', tokenId: 't1', side: 'long', entryPrice: 100, quantity: 5, value: 500,
        leverage: 5, margin: 100, liquidationPrice: 90, unrealizedPnl: 0, roe: 0,
      }];
      const fills = mode === 'open'
        ? [{ orderId: 'o1', tokenId: 't1', side: 'open_long' as const, filledValue: 500, filledTokenQty: 5, avgPrice: 100, leverage: 5 }]
        : [{
            orderId: 'o2', tokenId: 't1', side: 'close_long' as const,
            filledValue: mode === 'partial' ? 240 : 600,
            filledTokenQty: mode === 'partial' ? 2 : 5,
            avgPrice: 120, leverage: 5,
          }];
      let seq = 0;
      const res = settleFuturesFills({
        fills, positions, tokens: [{ id: 't1', code: 'T1' }], round: 7,
        makeId: () => `id-${++seq}`, rnd: () => 0.5,
        liquidationPriceOf: calculateLiquidationPrice,
      });
      return {
        positions: res.positions,
        inputQuantity: positions.length > 0 ? positions[0].quantity : null,
        availableDelta: res.availableCapitalDelta,
        frozenDelta: res.frozenCapitalDelta,
        openMarginLocked: res.openMarginLocked,
        filledOrderCount: res.filledOrderCount,
        totalPnl: res.totalPnl,
        totalReturnMargin: res.totalReturnMargin,
        openTrades: res.openTradeRecords,
        closeTrades: res.closeTradeRecords,
        retail: res.newRetailPositions,
      };
    };

    // 【开发自检】域三-2 散户强平纯函数：合成盘口/持仓跑通吃单、ADL、玩家挂单成交
    (window as unknown as Record<string, unknown>).__RETAIL_LIQ_TEST__ = (opts?: { mode?: 'long' | 'short' | 'none' }) => {
      const mode = opts?.mode ?? 'long';
      const tokenId = 't1';
      let seq = 0;
      let rndCalls = 0;
      const makeBook = (): FuturesOrderBook => {
        if (mode === 'long') {
          return {
            bids: [
              { price: 90, quantity: 4, total: 360, isPlayer: false },
              { price: 89, quantity: 100, total: 8900, isPlayer: true, orderId: 'ord-1' },
            ],
            asks: [{ price: 91, quantity: 100, total: 9100, isPlayer: false }],
            lastPrice: 90, markPrice: 90, indexPrice: 90,
            totalBidQuantity: 104, totalAskQuantity: 100,
          } as unknown as FuturesOrderBook;
        }
        if (mode === 'short') {
          return {
            bids: [{ price: 90, quantity: 100, total: 9000, isPlayer: false }],
            asks: [{
              price: 91, quantity: 100, total: 9100, isPlayer: false,
              isADL: true, adlPositionId: 'p-pos-1', adlOwnerType: 'player', adlOwnerId: 'me', adlSide: 'long',
            }],
            lastPrice: 90, markPrice: 91, indexPrice: 91,
            totalBidQuantity: 100, totalAskQuantity: 100,
          } as unknown as FuturesOrderBook;
        }
        return {
          bids: [{ price: 90, quantity: 100, total: 9000, isPlayer: false }],
          asks: [{ price: 91, quantity: 100, total: 9100, isPlayer: false }],
          lastPrice: 90, markPrice: 90, indexPrice: 90,
          totalBidQuantity: 100, totalAskQuantity: 100,
        } as unknown as FuturesOrderBook;
      };
      const books: Record<string, FuturesOrderBook> = { [tokenId]: makeBook() };
      const beforeBookJson = JSON.stringify(books[tokenId]);
      const retailPosition = {
        id: 'r-1', tokenId, side: mode === 'short' ? ('short' as const) : ('long' as const),
        entryPrice: 100, quantity: 1000, leverage: 10, margin: 100,
        liquidationPrice: mode === 'none' ? 10 : mode === 'short' ? 90 : 95, createdAt: 0,
      };
      const arbitrageExtra = { ...retailPosition, id: 'arb-1', side: 'short' as const };
      const tokensById = new Map<string, Token>([[tokenId, { id: tokenId, code: 'T1' } as unknown as Token]]);
      const futuresOrders = [{ id: 'ord-1', tokenId, side: 'open_long', quantity: 1000, leverage: 5, marginMode: 'isolated' } as unknown as FuturesOrder];
      const playerPositions: FuturesPosition[] = mode === 'short'
        ? [{ id: 'p-pos-1', tokenId, side: 'long', entryPrice: 100, quantity: 5, value: 500, leverage: 5, margin: 100, liquidationPrice: 50, unrealizedPnl: 0, roe: 0 }]
        : [];
      const result = matchRetailLiquidations({
        retailPositionsByToken: new Map([[tokenId, mode === 'none' ? [retailPosition] : [retailPosition]]]),
        tokensById,
        books,
        retailPositions: [],
        playerPositions,
        futuresOrders,
        aiTraders: [],
        aiMarketMakers: [],
        availableCapital: 1000,
        frozenCapital: 200,
        round: 9,
        makeId: () => `gen-${++seq}`,
        rnd: () => { rndCalls += 1; return 0.5; },
        arbitrageRetailPositions: [arbitrageExtra],
        newRetailPositionsFromFills: [],
      });
      const ordersAfter = applyPlayerOrderFillUpdates(futuresOrders, result.mergedOrderFills);
      return {
        mode,
        hasLiquidations: result.hasLiquidations,
        liquidatedIds: result.liquidatedPositionIds,
        liquidationAmounts: result.liquidationAmountsByToken,
        bookAfter: result.books[tokenId] ?? null,
        inputBookUnchanged: JSON.stringify(books[tokenId]) === beforeBookJson,
        newRetail: result.newRetailPositionsFromLiquidation,
        rndCalls,
        adlFillCount: result.adlFillCount,
        adlPlayerUpdates: result.adlPlayerPositionUpdates,
        adlTradeRecords: result.adlTradeRecords,
        adlPnl: result.adlPnl,
        adlReturnMargin: result.adlReturnMargin,
        mergedOrderFills: result.mergedOrderFills,
        playerOpenFills: result.playerOpenFills,
        playerOpenMarginTotal: result.playerOpenMarginTotal,
        playerOpenTradeRecords: result.playerOpenTradeRecords,
        ordersAfter,
        crossMarginPool: result.crossMarginPool,
        retailRebuildCount: result.retailRebuildFromGroups.length,
      };
    };

    // 【域三-3 自检】玩家强平：全仓/逐仓、吃单、ADL、挂单成交、不可变性
    (window as unknown as Record<string, unknown>).__PLAYER_LIQ_TEST__ = (opts?: { mode?: 'isolated' | 'player' | 'cross' | 'none' | 'adl' }) => {
      const mode = opts?.mode ?? 'isolated';
      const tokens = [{ id: 't1', code: 'AAA' }, { id: 't2', code: 'BBB' }];
      const tokensById = new Map(tokens.map(t => [t.id, t as unknown as Token]));
      const baseBook = (tokenId: string, markPrice: number, bids: unknown[], asks: unknown[]) => ({
        tokenId, bids, asks, lastPrice: markPrice, markPrice, indexPrice: markPrice,
        totalBidQuantity: 0, totalAskQuantity: 0,
      }) as unknown as FuturesOrderBook;
      const lvl = (price: number, quantity: number, extra?: Record<string, unknown>) =>
        ({ price, quantity, total: price * quantity, isPlayer: false, ...extra });

      let positions: FuturesPosition[];
      let books: Record<string, FuturesOrderBook>;
      let futuresOrders: FuturesOrder[] = [];
      const retailFixtures: RetailPosition[] = [];
      let aiTraders: AITrader[] = [];
      let aiMarketMakers: AIMarketMaker[] = [];

      if (mode === 'cross') {
        positions = [
          { id: 'p1', tokenId: 't1', side: 'long', entryPrice: 100, quantity: 1, value: 100, leverage: 2, margin: 50, liquidationPrice: 80, marginMode: 'cross', unrealizedPnl: 0, roe: 0 },
          { id: 'p2', tokenId: 't2', side: 'short', entryPrice: 50, quantity: 1, value: 50, leverage: 2, margin: 25, liquidationPrice: 60, marginMode: 'cross', unrealizedPnl: 0, roe: 0 },
        ] as unknown as FuturesPosition[];
        books = {
          t1: baseBook('t1', 50, [lvl(50, 10)], [lvl(51, 10)]),
          t2: baseBook('t2', 50, [lvl(49, 10)], [lvl(50, 10)]),
        };
      } else if (mode === 'none') {
        positions = [{ id: 'p1', tokenId: 't1', side: 'long', entryPrice: 100, quantity: 10, value: 1000, leverage: 10, margin: 100, liquidationPrice: 10, marginMode: 'isolated', unrealizedPnl: 0, roe: 0 }] as unknown as FuturesPosition[];
        books = { t1: baseBook('t1', 90, [lvl(90, 100)], [lvl(91, 100)]) };
      } else if (mode === 'adl') {
        positions = [
          { id: 'p1', tokenId: 't1', side: 'long', entryPrice: 100, quantity: 10, value: 1000, leverage: 10, margin: 100, liquidationPrice: 95, marginMode: 'isolated', unrealizedPnl: 0, roe: 0 },
          { id: 'p2', tokenId: 't1', side: 'long', entryPrice: 80, quantity: 5, value: 400, leverage: 5, margin: 80, liquidationPrice: 70, marginMode: 'isolated', unrealizedPnl: 0, roe: 0 },
        ] as unknown as FuturesPosition[];
        books = { t1: baseBook('t1', 90, [lvl(90, 10, { isADL: true, adlPositionId: 'p2', adlOwnerType: 'player', adlSide: 'long' })], [lvl(91, 100)]) };
      } else {
        positions = [{ id: 'p1', tokenId: 't1', side: 'long', entryPrice: 100, quantity: 10, value: 1000, leverage: 10, margin: 100, liquidationPrice: 95, marginMode: 'isolated', unrealizedPnl: 0, roe: 0 }] as unknown as FuturesPosition[];
        books = {
          t1: baseBook('t1', 90,
            mode === 'player'
              ? [lvl(90, 4), lvl(89, 100, { isPlayer: true, orderId: 'ord-1' })]
              : [lvl(90, 4), lvl(89, 100)],
            [lvl(91, 100)]),
        };
        if (mode === 'player') {
          futuresOrders = [{ id: 'ord-1', tokenId: 't1', side: 'open_long', quantity: 1000, price: 89, leverage: 5, marginMode: 'isolated', status: 'pending', createdAt: 0 } as unknown as FuturesOrder];
        }
      }

      const bookSnapshot = JSON.stringify(books);
      const positionsSnapshot = JSON.stringify(positions);

      const evaluation = evaluatePlayerLiquidations({
        positions, books, tokensById, availableCapital: mode === 'cross' ? 10 : 1000, frozenCapital: 0,
        pnlOf: calculateFuturesPnl, crossLiquidationPriceOf: calculateCrossLiquidationPrice,
      });
      const plan = settlePlayerLiquidations({
        liquidatedPositions: evaluation.liquidatedPositions,
        remainingPositions: evaluation.remainingPositions,
        books,
        tokens,
        futuresOrders,
        prevPositions: positions,
        retailPositions: retailFixtures,
        aiTraders,
        aiMarketMakers,
        round: 7,
        makeId: () => 'id-' + Math.random().toString(36).slice(2, 8),
        rnd: () => 0.5,
        liquidationPriceOf: calculateLiquidationPrice,
        crossLiquidationPriceOf: calculateCrossLiquidationPrice,
        crossMarginPool: evaluation.crossMarginPool,
        crossLiquidationTriggered: evaluation.crossLiquidationTriggered,
      });

      return {
        liquidatedIds: evaluation.liquidatedPositions.map(p => p.id),
        crossTriggered: evaluation.crossLiquidationTriggered,
        crossMarginPool: evaluation.crossMarginPool,
        liquidationCount: plan.liquidationCount,
        cashOps: plan.cashOps,
        positionsAfter: plan.positionsAfter,
        remainingCount: evaluation.remainingPositions.length,
        newRetail: plan.newRetailPositions,
        toasts: plan.toasts,
        tradeHistory: plan.tradeHistoryPrepend,
        liquidationDeltas: plan.liquidationDeltas,
        mergedOrderFills: plan.mergedOrderFills,
        playerOpenFills: plan.playerOpenFills,
        playerOpenMarginTotal: plan.playerOpenMarginTotal,
        adlPlayerUpdates: plan.adlPlayerPositionUpdates,
        adlReturnMargin: plan.adlReturnMargin,
        adlPnl: plan.adlPnl,
        bookUnchanged: JSON.stringify(books) === bookSnapshot,
        positionsUnchanged: JSON.stringify(positions) === positionsSnapshot,
      };
    };


    // 【域四-3 自检】下架四步强平结算纯函数（生产构建不注入）
    (window as unknown as Record<string, unknown>).__DELIST_SETTLE_TEST__ = () => {
      const tokens = [
        { id: 't1', code: 'AAA', name: 'AAA Name', delistAvgPrice: 100 },
        { id: 't2', code: 'BBB', name: 'BBB Name' },
        { id: 't3', code: 'CCC', name: 'CCC Name' },
      ] as unknown as Token[];
      const delistedTokensWithReason = [
        { id: 't1', code: 'AAA', reason: 'liquidity' as DelistReason },
        { id: 't2', code: 'BBB', reason: 'fraud' as DelistReason },
      ];
      const playerPositions = [
        { id: 'p1', tokenId: 't1', side: 'long', entryPrice: 80, quantity: 10, margin: 100 },
        { id: 'p2', tokenId: 't2', side: 'long', entryPrice: 80, quantity: 4, margin: 40 },
        { id: 'p3', tokenId: 't3', side: 'long', entryPrice: 10, quantity: 1, margin: 10 },
      ] as unknown as FuturesPosition[];
      const playerClosePrice = new Map<string, number>([['p1', 130]]);
      const aiKey = 'ai1::t1|long|80|10|100';
      const aiClosePrices = new Map<string, number[]>([[aiKey, [120]]]);
      const aiTraders = [{
        id: 'ai1',
        futuresPositions: [{ tokenId: 't1', side: 'long', entryPrice: 80, quantity: 10, margin: 100 }],
        availableCapital: 1000,
        pendingLimitOrders: [{ tokenId: 't1' }, { tokenId: 't3' }],
      }] as unknown as AITrader[];
      const mmKey = 'mm1::t2|short|60|5|50';
      const mmClosePrices = new Map<string, number[]>([[mmKey, [65]]]);
      const aiMarketMakers = [{
        id: 'mm1',
        futuresPositions: [{ tokenId: 't2', side: 'short', entryPrice: 60, quantity: 5, margin: 50 }],
        availableCapital: 500,
        pendingLimitOrders: [{ tokenId: 't2' }],
      }] as unknown as AIMarketMaker[];

      const positionsSnapshot = JSON.stringify(playerPositions);
      const aiQueuesSnapshot = JSON.stringify(Array.from(aiClosePrices.entries()));

      const result = settleDelistedTokens({
        newRound: 7,
        tokens,
        delistedTokensWithReason,
        delistAvgPriceByToken: { t2: 50 },
        playerClosePrice,
        aiClosePrices,
        mmClosePrices,
        playerPositions,
        aiTraders,
        aiMarketMakers,
        makeId: () => 'id-' + Math.random().toString(36).slice(2, 8),
      });

      return {
        delistPriceByToken: result.delistPriceByToken,
        playerPositions: result.playerPositions.map(pos => ({ id: pos.id, tokenId: pos.tokenId })),
        cashOps: result.cashOps,
        tradeRecords: result.tradeRecords.map(t => ({
          tokenId: t.tokenId, tokenCode: t.tokenCode, action: t.action, side: t.side,
          price: t.price, quantity: t.quantity, pnl: t.pnl, margin: t.margin,
        })),
        ai: {
          futuresCount: result.aiTraders[0].futuresPositions.length,
          availableCapital: result.aiTraders[0].availableCapital,
          orderTokenIds: result.aiTraders[0].pendingLimitOrders.map((o: { tokenId: string }) => o.tokenId),
        },
        mm: {
          futuresCount: result.aiMarketMakers[0].futuresPositions.length,
          availableCapital: result.aiMarketMakers[0].availableCapital,
          orderTokenIds: result.aiMarketMakers[0].pendingLimitOrders.map((o: { tokenId: string }) => o.tokenId),
        },
        announcements: result.announcements.map(a => ({
          type: a.type, status: a.status, title: a.title, tokenCode: a.tokenCode,
          tokenName: a.tokenName, round: a.round, day: a.day,
        })),
        toasts: result.toasts,
        immutable: {
          positions: JSON.stringify(playerPositions) === positionsSnapshot,
          aiQueues: JSON.stringify(Array.from(aiClosePrices.entries())) === aiQueuesSnapshot,
        },
      };
    };


    // 【域四-4 自检】回合内回购销毁纯函数（生产构建不注入）
    (window as unknown as Record<string, unknown>).__BUYBACK_TEST__ = (opts?: { mode?: 'project' | 'both' | 'nobook' | 'ineligible' | 'smallpool' }) => {
      const mode = opts?.mode ?? 'project';
      const round = mode === 'both' || mode === 'nobook' ? 24 : 12;
      const mkToken = (over: Record<string, unknown> = {}) => ({
        id: 't1', code: 'AAA', name: 'AAA', tokenType: 'meme',
        isPlayerCreated: true, autoBurnRevenue: true,
        projectFundPool: 1000, circulatingSupply: 1000, totalSupply: 1000,
        currentPrice: 10, createdAt: 0, lastClaimRound: 0, volumeSinceLastClaim: 0,
        ...over,
      }) as unknown as Token;
      const tokens = [mkToken(mode === 'ineligible' ? { autoBurnRevenue: false } : mode === 'smallpool' ? { projectFundPool: 50 } : {})];
      const candle = (i: number) => ({ time: i, open: 10, high: 10, low: 10, close: 10, volume: 1 }) as unknown as Candle;
      const candles = Array.from({ length: 24 }, (_, i) => candle(i));
      const ask = (price: number, quantity: number) => ({ price, quantity, total: price * quantity, isPlayer: false }) as unknown as OrderBookEntry;
      const books = mode === 'nobook'
        ? {}
        : { t1: { tokenId: 't1', bids: [], asks: [ask(10, 50), ask(12, 100)], lastPrice: 10, totalBidQuantity: 0, totalAskQuantity: 150 } as unknown as Level2OrderBook };
      const booksSnapshot = JSON.stringify(books);

      const result = computeBuybackBurns({
        round,
        tokens,
        books,
        candlesUpdates: { t1: candles },
        candlesState: {},
      });

      return {
        bookUpdates: result.bookUpdates,
        burnUpdates: result.burnUpdates,
        toasts: result.toasts,
        burnCount: result.burnUpdates.length,
        bookUpdateKeys: Object.keys(result.bookUpdates),
        immutable: {
          books: JSON.stringify(books) === booksSnapshot,
          originalAsks: (books as Record<string, Level2OrderBook | undefined>).t1?.asks.length ?? 0,
        },
      };
    };


    // 【域四-5 自检】回合事件系统纯函数（生产构建不注入）
    (window as unknown as Record<string, unknown>).__ROUND_EVENTS_TEST__ = (opts?: { mode?: string }) => {
      const mode = opts?.mode ?? 'daily';
      const bullEventId = BULL_EVENTS[0]?.id ?? 'market-bull-1';
      const bullLevel = getEventById(bullEventId)?.level ?? 1;
      const mkToken = (id: string, code: string, over: Record<string, unknown> = {}) => ({
        id, code, name: code, cexListed: true, tokenType: 'meme',
        currentPrice: 1, circulatingSupply: 1e6, change24h: 0,
        ...over,
      }) as unknown as Token;
      const tokens = [mkToken('t1', 'T1'), mkToken('t2', 'T2')];
      const tokensSnapshot = JSON.stringify(tokens);
      let rndCalls = 0;
      const rnd = () => { rndCalls++; return 0; };
      const base = {
        tokens,
        round: 5,
        day: 1,
        eventHistory: {} as Record<string, number>,
        todayEvent: null as { day: number; eventId: string } | null,
        activeEvent: null as ActiveGameEvent | null,
        suddenEvent: null as Parameters<typeof resolveRoundEvents>[0]['suddenEvent'],
        exchangeDownRound: null as number | null,
        pendingDevHack: null as { eventId: string; tokenId: string } | null,
        pendingDevTokenEvent: null as { tokenId: string; type: 'bull' | 'bear'; level: number } | null,
        devTokenEvent: null as Parameters<typeof resolveRoundEvents>[0]['devTokenEvent'],
        fearGreedIndex: 50,
        rnd,
        makeId: () => 'id-' + (rndCalls + 1),
        pickDaily: () => null as { day: number; eventId: string } | null,
        rollSudden: () => false,
      };
      let input = { ...base };
      if (mode === 'daily') {
        input = { ...base, round: 20, day: 1, todayEvent: { day: 1, eventId: bullEventId } };
      } else if (mode === 'expire') {
        input = { ...base, round: 50, day: 3, activeEvent: { eventId: bullEventId, type: 'bull', level: bullLevel, day: 1, announcementRound: 10 } as ActiveGameEvent };
      } else if (mode === 'suddenDev') {
        input = { ...base, round: 7, day: 1, pendingDevHack: { eventId: 'sudden-hack', tokenId: 't1' } };
      } else if (mode === 'suddenMissingToken') {
        input = { ...base, round: 7, day: 1, pendingDevHack: { eventId: 'sudden-hack', tokenId: 'nope' } };
      } else if (mode === 'suddenRandom') {
        input = { ...base, round: 7, day: 1, rollSudden: () => true };
      } else if (mode === 'devToken') {
        input = { ...base, round: 9, day: 1, pendingDevTokenEvent: { tokenId: 't1', type: 'bull' as const, level: 2 } };
      } else if (mode === 'devTokenExpire') {
        input = { ...base, round: 30, day: 2, devTokenEvent: { tokenId: 't1', type: 'bull' as const, level: 2, startRound: 0 } };
      } else if (mode === 'notEventDay') {
        input = { ...base, round: 5, day: 1, pickDaily: () => ({ day: 1, eventId: bullEventId }), todayEvent: null };
      }
      const eventHistorySnapshot = JSON.stringify(input.eventHistory);
      const result = resolveRoundEvents(input);
      return {
        ...result,
        rndCalls,
        expectedBullId: bullEventId,
        expectedBullLevel: bullLevel,
        immutable: {
          tokens: JSON.stringify(tokens) === tokensSnapshot,
          eventHistory: JSON.stringify(input.eventHistory) === eventHistorySnapshot,
        },
      };
    };

  }, []);
  // 【库存守恒自检】每回合校验：cexReserve ≥ 玩家 cexBalance + AI/做市商现货持仓；异常时记录并钳制。
  useEffect(() => {
    if (tokens.length === 0) return;
    const aiHold: Record<string, number> = {};
    aiTraders.forEach(trader => trader.positions.forEach(pos => { aiHold[pos.tokenId] = (aiHold[pos.tokenId] || 0) + pos.quantity; }));
    const mmHold: Record<string, number> = {};
    aiMarketMakers.forEach(mm => mm.positions.forEach(pos => { mmHold[pos.tokenId] = (mmHold[pos.tokenId] || 0) + pos.quantity; }));
    const violations: Array<{ tokenId: string; code: string; reserve: number; accounted: number; diff: number }> = [];
    tokens.forEach(token => {
      const check = checkReserveConservation(
        token.cexReserve || 0,
        playerTokenBalances[token.id]?.cexBalance || 0,
        aiHold[token.id] || 0,
        mmHold[token.id] || 0
      );
      if (!check.ok) violations.push({ tokenId: token.id, code: token.code, reserve: check.cexReserve, accounted: check.accounted, diff: check.diff });
    });
    // 【开发自检】暴露守恒与可挂卖盘数据，便于自动化验证（生产构建不注入）
    if (import.meta.env.DEV) {
      (window as unknown as Record<string, unknown>).__INVENTORY_CHECK__ = tokens.map(token => {
        const cexReserve = token.cexReserve || 0;
        const playerCexBalance = playerTokenBalances[token.id]?.cexBalance || 0;
        const ai = aiHold[token.id] || 0;
        const mm = mmHold[token.id] || 0;
        const asksTotal = (tokenOrderBookMap[token.id]?.asks || []).reduce((sum, a) => sum + a.quantity, 0);
        const marketAsksTotal = (tokenOrderBookMap[token.id]?.asks || []).reduce((sum, a) => (a.isPlayer ? sum : sum + a.quantity), 0);
        const check = checkReserveConservation(cexReserve, playerCexBalance, ai, mm);
        const dexReserve = token.dexReserve || 0;
        const physicalTotal = cexReserve + dexReserve + (token.unvestedSupply || 0);
        return {
          tokenId: token.id, code: token.code, round: currentRound,
          cexReserve, dexReserve, playerCexBalance, aiHolding: ai, marketMakerHolding: mm,
          accounted: check.accounted, ok: check.ok,
          availableAskLiquidity: computeAvailableAskLiquidity(cexReserve, playerCexBalance, ai, mm),
          asksTotal, marketAsksTotal,
          totalSupply: token.totalSupply, circulatingSupply: token.circulatingSupply,
          unvestedSupply: token.unvestedSupply || 0,
          physicalTotal,
          physicalDiff: physicalTotal - token.totalSupply,
        };
      });
    }
    if (violations.length === 0) return;
    // 【库存守恒·修复】CEX 库存是物理上限：占用量超过库存时不能凭空抬高库存（会掩盖超发并让库存量异常膨胀），
    // 而是把 AI/做市商的超额现货持仓按比例收缩到物理可容纳范围；玩家持仓受保护（必要时仅补足玩家所需库存）。
    const reserveFixMap = new Map<string, number>();
    const aiScaleMap = new Map<string, number>();
    const mmScaleMap = new Map<string, number>();
    violations.forEach(v => {
      const token = tokens.find(t => t.id === v.tokenId);
      if (!token) return;
      const cexReserve = token.cexReserve || 0;
      const playerBal = playerTokenBalances[token.id]?.cexBalance || 0;
      if (playerBal > cexReserve + 1e-6) {
        reserveFixMap.set(token.id, playerBal);
        aiScaleMap.set(token.id, 0);
        mmScaleMap.set(token.id, 0);
        return;
      }
      const allowedForAimm = Math.max(0, cexReserve - playerBal);
      const aiQty = aiHold[token.id] || 0;
      const mmQty = mmHold[token.id] || 0;
      const total = aiQty + mmQty;
      if (total > allowedForAimm + 1e-6) {
        const scale = total > 0 ? allowedForAimm / total : 0;
        if (aiQty > 0) aiScaleMap.set(token.id, scale);
        if (mmQty > 0) mmScaleMap.set(token.id, scale);
      }
    });
    if (import.meta.env.DEV) console.warn('[库存守恒] 占用量超过 CEX 物理库存，已收缩 AI/做市商超额持仓并补足玩家所需库存', violations.slice(0, 8));
    if (reserveFixMap.size > 0) setTokens(prev => prev.map(tk => reserveFixMap.has(tk.id) ? { ...tk, cexReserve: Math.max(tk.cexReserve || 0, reserveFixMap.get(tk.id)!) } : tk));
    if (aiScaleMap.size > 0) setAiTraders(prev => prev.map(tr => ({
      ...tr,
      positions: tr.positions.map(p => {
        const scale = aiScaleMap.get(p.tokenId);
        return scale !== undefined ? { ...p, quantity: p.quantity * scale } : p;
      }),
    })));
    if (mmScaleMap.size > 0) setAiMarketMakers(prev => prev.map(mm => ({
      ...mm,
      positions: mm.positions.map(p => {
        const scale = mmScaleMap.get(p.tokenId);
        return scale !== undefined ? { ...p, quantity: p.quantity * scale } : p;
      }),
    })));
  }, [currentRound, tokens, playerTokenBalances]);


  const [dayCount, setDayCount] = useTrackedState("dayCount", 1);
