  // 计算24h成交量最高的代币（用于代币搜索弹窗默认列表）
  const topTokensByVolume = useMemo(() => {
    // 计算每个代币的24h成交量
    const tokenVolumes: { token: Token; volume: number }[] = tokens.map(token => {
      const candles = tokenCandlesMap[token.id] || [];
      // 取最近24根K线的成交量总和
      const recentCandles = candles.slice(-24);
      const volume = recentCandles.reduce((sum, c) => sum + (c.volume || 0), 0);
      return { token, volume };
    });
    // 按成交量降序排序，取前10
    tokenVolumes.sort((a, b) => b.volume - a.volume);
    return tokenVolumes.slice(0, 10).map(tv => tv.token);
  }, [tokens, tokenCandlesMap]);
  
