  // 计算24小时涨跌幅（用于显示，不影响游戏机制）
  // 24小时前 = 24个回合前
  // 使用缓存优化，避免重复计算
  const token24hChangeCacheRef = useRef<Map<string, number>>(new Map());
  
  const getToken24hChange = useCallback((token: Token): number => {
    // 缓存键带上当前价格与小时序列长度：避免「价格已更新、回合号尚未更新」的中间渲染把旧值缓存成新回合值
    const cacheKey = `${token.id}-${currentRound}-${token.currentPrice}-${token.hourlyPrices?.length ?? 0}`;
    const cached = token24hChangeCacheRef.current.get(cacheKey);
    if (cached !== undefined) return cached;
    
    const price24hAgo = findPrice24hAgo(token.hourlyPrices, token.initialPrice, currentRound);
    const result = compute24hChangePercent(token.currentPrice, price24hAgo);
    
    // 缓存结果，限制缓存大小
    if (token24hChangeCacheRef.current.size > 100) {
      // 清理旧缓存
      const keys = Array.from(token24hChangeCacheRef.current.keys());
      keys.slice(0, 50).forEach(key => token24hChangeCacheRef.current.delete(key));
    }
    token24hChangeCacheRef.current.set(cacheKey, result);
    
    return result;
  }, [currentRound]);
  
