                  positions
                    .filter(pos => !pos.tokenId.startsWith('lp-'))
                    .slice()
                    .map(pos => {
                      const token = tokens.find(t => t.id === pos.tokenId);
                      const currentValue = pos.quantity * (token?.currentPrice || 0);
                      return { ...pos, currentValue, token };
                    })
                    .sort((a, b) => b.currentValue - a.currentValue)
                    .map(pos => {
                      const pnl = pos.currentValue - pos.avgCost * pos.quantity;
                      const totalCost = pos.avgCost * pos.quantity;
                      const pnlPercent = totalCost > 0 ? (pnl / totalCost) * 100 : 0;
                      return (
                        <div
                          key={pos.id}
                          className={`position-item ${pos.tokenId === selectedTokenId ? 'current-token' : ''}`}
                          onClick={() => {
                            setSelectedTokenId(pos.tokenId);
                          }}
                        >
                          <div className="position-header">
                            <span className="position-token">{pos.token?.code}</span>
                            <span className={`position-pnl ${pnl >= 0 ? 'up' : 'down'}`}>
                              {pnl >= 0 ? '+' : ''}${formatNumber(pnl)} ({pnlPercent >= 0 ? '+' : ''}{pnlPercent.toFixed(2)}%)
                            </span>
                          </div>
                          <div className="position-detail">
                            <span>数量 {formatNumber(pos.quantity, 4)}</span>
                            <span>成本 ${formatNumber(pos.avgCost)}</span>
                            <span>市值 ${formatNumber(pos.currentValue)}</span>
                          </div>
                        </div>
                      );
                    })
